import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%A4%E3%83%B3%E3%83%89%E3%83%8D%E3%82%B7%E3%82%A2%E8%AA%9E%E3%81%AE%E3%81%97%E3%81%8F%E3%81%BF.html","title":"インドネシア語のしくみ","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.54,"words":462},"filePathRelative":"インドネシア語のしくみ.md"}`),a={name:`インドネシア語のしくみ.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="インドネシア語のしくみ" tabindex="-1"><a class="header-anchor" href="#インドネシア語のしくみ"><span>インドネシア語のしくみ</span></a></h1><p><a href="./インドネシア語.html">インドネシア語</a>の<a href="./書籍.html">書籍</a></p><p><a href="https://www.amazon.co.jp/dp/B07D72CMKV?&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=0889049456d9bc699042fc87eddea4db&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: インドネシア語のしくみ</a></p><p>しくみシリーズのインドネシア語版。 語順などを日本語の語順と無理やり合わせて説明しようとしてかえって面倒になっている所もあるが、 既出の単語でもしばらく経ったらちゃんと解説を入れるし、割と読みやすい。</p><p>ただ例えばスペイン語のしくみなどと比べると全体像が分かりにくい気はする。 文法的な決まりを大原則から説明してくような内容なのだが、 原則から外れる例が多くて原則を設けた意味があまり感じられない。</p><p>ただ暇な時に読んでいく感じでは読みやすく、 文法の知識は増えるのでこのシリーズに期待されている役割は果たしていると思う。</p><h2 id="実際のしくみ、まで読んだ-2026-11-08-日" tabindex="-1"><a class="header-anchor" href="#実際のしくみ、まで読んだ-2026-11-08-日"><span>実際のしくみ、まで読んだ 2026-11-08 (日)</span></a></h2><p><a href="./ニューエクスプレスインドネシア語.html">ニューエクスプレスインドネシア語</a>の息抜きとして読んでいて、実際のしくみ、まで来た。 途中消化不良になって良く分からなくなった部分もあるが、気にせず読み進めて実際のしくみまで来た。 ここまで来るとあとはおまけみたいなものなので、一応本書を終えたとは言えるんじゃないか。</p><p>てにをはのしくみ、のあたりはだいたい良くわからなくなるんじゃないかなぁ。 シンプルなルールで統一的にいろいろ説明出来る、という感じじゃなくて、 ルールはいろいろでてくるが適用可能な相手が少なくて単に各文を覚えるのに比べて楽になっているのかが微妙だし、 納得感が低い。</p><p>ただインドネシア語自体がそういう言語だと思うので、 「しくみ」シリーズとしてはこうなるものなのかな、と思う。 読む側としてもちゃんと理解しよう、と思うよりは、良く分からなくなった所は良く分からないな、と思いながらそのまま進む方がいいんじゃないか。 適度に区切りがあるので、分からない所も進めていくとそのうち区切りになるのでそこから先はまた新しい気持ちで読み進められはする。</p><p>個人的にはまぁまぁ当たりだったんじゃないか、という気はしている。 読み物的に読んで、こういう感じか、というのをふわっと知って、 たまに真面目な教科書の息抜きで進めたりすると意外と知識や単語が補強されたりして、効果もあったりする。 副読本として買っておいてちまちま読み進めるにはいいんじゃないか。</p><h2 id="なかなか良かった-読み終わり-2026-11-09-月" tabindex="-1"><a class="header-anchor" href="#なかなか良かった-読み終わり-2026-11-09-月"><span>なかなか良かった（読み終わり） 2026-11-09 (月)</span></a></h2><p>先ほど最後まで読み終わった。</p><p>最後まで読んだ結果、あまり何か記憶に残ったことは無い。出てきた単語もだいたい忘れてしまった。 ただ息抜きに読んで少し興味を持続させておく感じの役割は果たしていたし、 <a href="./ニューエクスプレスインドネシア語.html">ニューエクスプレスインドネシア語</a>で新規の単語や文法項目が大量に出てきて圧倒された時とかに、 少しこの本を読んでいろいろな単語に触れてから戻ったらすんなり進めたりと、 それなりに役にはたった。</p><p>この本単体で何かを学ぶというよりは、他の本で学んだことを少し幅を持たせる感じに使うのが良いと思う。 この本で見た単語を他の本で見た時に「あー、なんか見たことあるな、覚えてないけど」くらいの気持ちになれる。 知らないことばっかりよりはだいぶ敷居が下がる。 語順的な話も覚えられないが、他の本で出てきた時に「なんとなくそういう話あったな〜」という気分にはなる。</p><p>何より最後まで挫折せずに読めたので「しくみ」シリーズの目的は達成出来ていたと思う。</p><h3 id="音声が復習に良い" tabindex="-1"><a class="header-anchor" href="#音声が復習に良い"><span>音声が復習に良い</span></a></h3><p>最後まで読んで終わりでいいか、と思いつつ、そういえば音声もダウンロードしてたな、と聞いてみたら、これが結構良く出来ている。</p><p>取捨選択が上手くされていて、頻出例文みたいになっている。しかも同じ文を二回ずつ読み、二回目がゆっくりなので理解しやすい。 頻出例文を覚えつつ、関連する文法解説を本文を軽く読み直す感じにすると、サクサク進んで結構良い。</p><p>全部読み直すほどのモチベーションは無いのだが、音声が数ページおきくらいに進んでいくので、 聞いていて、「あれ？これってなんだっけ」とぺらぺらめくる、という感じでやっていたら、今p92まで来た。 本文も読み直さないでも見出しとパッと目に入る文だけでだいたい内容を把握出来るので、意外とサクサク進める。</p><p>しかも一回目は全然頭に入らなかった文法とか単語も、こうやって復習すると結構スルスル入ってくる。 これはいいかもしれない。</p><p>終わりにするつもりだったが気が変わった。もう何回か音声中心で復習してみよう。</p>`,22)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};